SELECT user_record.*
FROM sys_user user_record

    user_record.is_deleted = 0

        AND (
            user_record.username LIKE CONCAT('%', #{query.keyword}, '%')
            OR user_record.real_name LIKE CONCAT('%', #{query.keyword}, '%')
            OR user_record.phone_number LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND user_record.status = #{query.status}


        AND user_record.organization_id = #{query.organizationId}


        AND user_record.department_id = #{query.departmentId}


        AND EXISTS (
            SELECT 1
            FROM rel_user_role user_role
            WHERE user_role.user_id = user_record.id
              AND user_role.role_id = #{query.roleId}
        )


ORDER BY user_record.id DESC
